جریان نقد عملیاتی هفتهٔ گذشته یک‌باره منفی بزرگ شده و مدیرعامل نگران است که روند بد شده. ببین این جهش چیست و آیا تکرار می‌شود؟ (مدیر مالی — صنایع شیمیایی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cash_flow_statement",
      "description": "صورت جریان وجوه نقد دوره به تفکیک بخش",
      "dimensions": [
        "period",
        "section"
      ],
      "measures": [
        "amount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "operating_cash_flow",
      "description": "جریان نقد عملیاتی",
      "formula": "دریافت‌ها از عملیات - پرداخت‌های عملیاتی",
      "unit": "میلیون تومان",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت تولیدی-بازرگانی میانه‌حجم؛ فروش عمدتاً نسیه به شرکت‌های صنعتی و بخشی خرد",
    "دورهٔ حسابداری ماهانه؛ گزارش‌ها تا پایان همان ماه در دسترس‌اند"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "operating_cash_flow",
    "granularity": "week",
    "range": "last_4_weeks"
  }
}

TOOL_OBSERVATION:
{
  "operating_cash_flow_weekly": [
    {
      "week": 1,
      "net_m_toman": 50
    },
    {
      "week": 2,
      "net_m_toman": 49
    },
    {
      "week": 3,
      "net_m_toman": 48
    },
    {
      "week": 4,
      "net_m_toman": -196
    }
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cash_flow_statement",
    "filters": {
      "period": "week_4",
      "section": "operating"
    }
  }
}

TOOL_OBSERVATION:
{
  "week4_items": {
    "پرداخت مالیات عملکرد قطعی سال قبل": 245,
    "سایر اقلام جاری": 49,
    "note": "پرداخت سالانه است؛ در هیچ‌یک از هفته‌های دیگر سال مشابه ندارد"
  }
}

نقش سازمانی: مدیر مالی (cfo)

درخواست کاربر:
به‌عنوان مدیرعامل می‌خواهم بدانم مهم‌ترین ریسک مالی این ماه از نگاه تو چیست و کجا باید تمرکز کنیم. (مدیر مالی در گفتگو با مدیرعامل — تولیدی تجهیزات صنعتی)

