هزینهٔ هر استخدام این ماه یک‌باره به 161 میلیون رسیده در حالی که قبلش حدود 28 بود. این جهش چیست؟ (مدیر منابع انسانی — هلدینگ خدماتی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "hires",
      "description": "استخدام‌ها: تعداد، هزینه و منبع جذب",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "count",
        "cost_m_toman"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "cost_per_hire",
      "description": "هزینهٔ هر استخدام",
      "formula": "مجموع هزینهٔ جذب و آموزش / تعداد استخدام",
      "unit": "میلیون تومان",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "cost_per_hire",
    "granularity": "month",
    "range": "last_6_months"
  }
}

