نقش سازمانی: مدیر منابع انسانی (hr_manager)

درخواست کاربر:
غیبت «واحد تحقیق و توسعه» این ماه از 0.2٪ به 1.3٪ رسیده در حالی که بقیهٔ واحدها ثابت‌اند. چرا؟ (مدیر منابع انسانی — زنجیرهٔ خرده‌فروشی)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "absence_records",
      "description": "روزهای غیبت به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "days",
        "planned_days"
      ]
    },
    {
      "dataset": "headcount",
      "description": "تعداد نیرو به تفکیک واحد و ماه",
      "dimensions": [
        "unit",
        "month"
      ],
      "measures": [
        "headcount"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "absence_rate",
      "description": "نرخ غیبت",
      "formula": "روزهای غیبت / روزهای کاری برنامه‌ریزی‌شده",
      "unit": "درصد",
      "dimensions": [
        "unit",
        "period"
      ]
    }
  ],
  "business_context": [
    "شرکت خدماتی-صنعتی با ۴۰۰ تا ۹۰۰ نفر نیرو در پنج واحد",
    "دورهٔ گزارش ماهانه؛ داده‌های منابع انسانی تا پایان همان ماه در دسترس است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "absence_rate"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month",
    "dimension": "unit"
  }
}

TOOL_OBSERVATION:
{
  "absence_rate_pct": {
    "prev_month": 0.2,
    "curr_month": 1.3,
    "unit": "واحد تحقیق و توسعه",
    "other_units": "بدون تغییر محسوس"
  }
}

TOOL_CALL:
