تا پایان تعمیر شاول ۳ حدود 35,000 تن در ماه کمبود تولید داریم. بین شیفت اضافه و پیمانکار استخراج کدام به‌صرفه‌تر است؟ (مدیر تولید معدن — معدن زغال‌سنگ کرمان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "production_plan_actual",
      "description": "برنامه و واقعی استخراج به تفکیک پیت و هفته",
      "dimensions": [
        "pit",
        "week"
      ],
      "measures": [
        "plan_tons",
        "actual_tons"
      ]
    },
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "extraction_rate",
      "description": "نرخ استخراج",
      "formula": "تن استخراج‌شده / روزهای کاری",
      "unit": "تن در روز",
      "dimensions": [
        "pit",
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با دو پیت فعال و کارخانهٔ فرآوری مجاور",
    "برنامهٔ تولید ماهانه و شاخص‌های فنی هفته‌به‌هفته به‌روز می‌شود"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "extraction_rate"
    ],
    "period": "curr_month",
    "comparison": "plan"
  }
}

TOOL_OBSERVATION:
{
  "extraction_vs_plan": {
    "plan_tons": 680000,
    "deficit_tons": 35000,
    "note": "کمبود ناشی از توقف شاول ۳ تا پایان تعمیر"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "cost_ledger",
    "filters": {
      "period": "curr_month",
      "component": "contractor"
    }
  }
}

TOOL_OBSERVATION:
{
  "option_contractor": {
    "rate_toman_per_ton": 220000,
