زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "cost_ledger",
      "description": "هزینهٔ عملیاتی به تفکیک جزء (سوخت، قطعات، دستمزد، پیمانکار)",
      "dimensions": [
        "component",
        "period"
      ],
      "measures": [
        "toman_per_ton"
      ]
    },
    {
      "dataset": "haul_report",
